def run(document, schema, options \\ []) do
  pipeline = Absinthe.Pipeline.for_document(schema, options)
  result = Absinthe.Pipeline.run(document, pipeline)

  case result do
    {:ok, %{result: result_value, errors: errors}} when errors == [] ->
      {:ok, result_value}

    {:ok, %{errors: errors}} ->
      {:error, Absinthe.Language.Error.format_errors(errors)}

    {:error, error} when is_binary(error) ->
      {:error, error}

    {:error, %{message: message}} ->
      {:error, message}

    {:error, error} ->
      {:error, inspect(error)}
  end
end

